-- External electronic signature is evidence; native HR approval and term activation remain separate.
CREATE TABLE ty_es_profile(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint REFERENCES ty_company(id),
 code text NOT NULL,name text NOT NULL,version int NOT NULL CHECK(version>0),provider text NOT NULL DEFAULT'esign_v3'CHECK(provider='esign_v3'),
 environment text NOT NULL CHECK(environment IN('sandbox','production')),app_id text NOT NULL,credential_cipher jsonb NOT NULL,
 evidence_ref text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),revision int NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,
 UNIQUE(group_id,code,version),CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL)
);
CREATE TABLE ty_es_party(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,profile_id bigint NOT NULL REFERENCES ty_es_profile(id),group_id bigint NOT NULL REFERENCES ty_group(id),
 company_id bigint REFERENCES ty_company(id),person_id bigint REFERENCES ty_person(id),kind text NOT NULL CHECK(kind IN('person','company')),local_key text NOT NULL,
 external_id text NOT NULL CHECK(external_id~'^[A-Za-z0-9_-]{1,120}$'),transactor_id text,
 valid_from date NOT NULL,valid_to date,evidence_ref text NOT NULL,
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','disabled')),revision int NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),created_at timestamptz NOT NULL DEFAULT now(),approved_at timestamptz,
 CHECK(valid_to IS NULL OR valid_to>valid_from),CHECK(kind='person'AND person_id IS NOT NULL AND transactor_id IS NULL OR kind='company'AND person_id IS NULL AND company_id IS NOT NULL AND transactor_id~'^[A-Za-z0-9_-]{1,120}$'),
 CHECK(status<>'approved'OR approved_by IS NOT NULL AND approved_at IS NOT NULL),
 EXCLUDE USING gist(profile_id WITH=,local_key WITH=,daterange(valid_from,valid_to,'[)')WITH&&)WHERE(status='approved'),
 EXCLUDE USING gist(profile_id WITH=,kind WITH=,external_id WITH=,daterange(valid_from,valid_to,'[)')WITH&&)WHERE(status='approved')
);
CREATE TABLE ty_es_intent(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,intent_key text NOT NULL UNIQUE,group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),person_id bigint NOT NULL REFERENCES ty_person(id),
 contract_id bigint NOT NULL REFERENCES ty_hr_contract(id),contract_revision int NOT NULL,contract_hash text NOT NULL,
 profile_id bigint NOT NULL REFERENCES ty_es_profile(id),profile_revision int NOT NULL,person_party_id bigint NOT NULL REFERENCES ty_es_party(id),person_party_revision int NOT NULL,company_party_id bigint NOT NULL REFERENCES ty_es_party(id),company_party_revision int NOT NULL,
 source_file_id bigint NOT NULL REFERENCES ty_hr_file_asset(id),source_sha256 text NOT NULL,filename text NOT NULL,contract_code text NOT NULL,flow_title text NOT NULL,positions jsonb NOT NULL,
 evidence_ref text NOT NULL,status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved','external_draft','signing','completed','accepted','unknown','blocked')),
 remote_file_id text,remote_flow_id text,remote_status int CHECK(remote_status IN(0,1,2,3,5,7)),remote_checked_at timestamptz,
 signed_file_id bigint REFERENCES ty_hr_file_asset(id),signed_sha256 text,signed_on date,receipt_cipher jsonb,verification_summary jsonb,
 revision int NOT NULL DEFAULT 1,created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,
 started_by bigint REFERENCES sys_account(id),accepted_by bigint REFERENCES sys_account(id),accepted_at timestamptz,accept_ref text,created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(profile_id,remote_flow_id),UNIQUE(profile_id,remote_file_id),
 CHECK(status NOT IN('approved','external_draft','signing','completed','accepted')OR approved_by IS NOT NULL AND approved_at IS NOT NULL),
 CHECK(status NOT IN('completed','accepted')OR signed_file_id IS NOT NULL AND signed_sha256 IS NOT NULL AND signed_on IS NOT NULL AND receipt_cipher IS NOT NULL),
 CHECK(status<>'accepted'OR accepted_by IS NOT NULL AND accepted_at IS NOT NULL AND length(btrim(accept_ref))>=4)
);
CREATE UNIQUE INDEX ty_es_one_live_contract ON ty_es_intent(contract_id)WHERE status NOT IN('blocked');
CREATE TABLE ty_es_job(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,intent_id bigint NOT NULL REFERENCES ty_es_intent(id),step text NOT NULL CHECK(step IN('upload','create','start','poll','retrieve','reconcile')),
 state text NOT NULL DEFAULT'queued'CHECK(state IN('queued','running','succeeded','failed','unknown')),requested_by bigint NOT NULL REFERENCES sys_account(id),
 expected_revision int NOT NULL,lease_key text,lease_until timestamptz,error_code text,remote_claim_id text,
 created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz,revision int NOT NULL DEFAULT 1,
 CHECK(state<>'running'OR lease_key IS NOT NULL AND lease_until IS NOT NULL)
);
CREATE UNIQUE INDEX ty_es_one_active_job ON ty_es_job(intent_id)WHERE state IN('queued','running');
CREATE FUNCTION fn_ty_es_profile_current(k bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.ty_es_profile p WHERE p.id=k AND p.status='approved'AND NOT EXISTS(SELECT 1 FROM public.ty_es_profile n WHERE n.group_id=p.group_id AND n.code=p.code AND n.status='approved'AND n.version>p.version))
$$;
CREATE FUNCTION fn_ty_es_party_current(k bigint)RETURNS boolean LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT EXISTS(SELECT 1 FROM public.ty_es_party b WHERE b.id=k AND b.status='approved'AND b.valid_from<=public.app_today()AND(b.valid_to IS NULL OR public.app_today()<b.valid_to)AND public.fn_ty_es_profile_current(b.profile_id))
$$;
CREATE FUNCTION fn_ty_es_config_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_es_profile%ROWTYPE;g bigint;pe bigint;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签配置保留历史，不可删除';END IF;
 IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['status','revision','approved_by','approved_at']IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','revision','approved_by','approved_at']OR OLD.status<>'draft'AND NEW.status<>'disabled'OR NEW.revision<>OLD.revision+1)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签已核内容不可改写，变更须新版本';END IF;
 IF TG_TABLE_NAME='ty_es_profile'THEN
  g:=NEW.group_id;IF NEW.company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company c WHERE c.id=NEW.company_id AND c.group_id=g)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签配置主体不在本集团';END IF;
 ELSE
  SELECT*INTO p FROM public.ty_es_profile WHERE id=NEW.profile_id;g:=NEW.group_id;pe:=NEW.person_id;
  IF p.group_id<>g OR NEW.local_key IS DISTINCT FROM (CASE WHEN NEW.kind='person'THEN 'person:'||NEW.person_id ELSE 'company:'||NEW.company_id END) OR NEW.person_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_person x WHERE x.id=NEW.person_id AND x.group_id=g)OR NEW.company_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_company x WHERE x.id=NEW.company_id AND x.group_id=g)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签主体须与本集团明确人员或公司对应';END IF;
 END IF;
 IF NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,g,pe)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签配置与主体映射须独立且非受益人核准';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_es_profile_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_es_profile FOR EACH ROW EXECUTE FUNCTION fn_ty_es_config_guard();
CREATE TRIGGER ty_es_party_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_es_party FOR EACH ROW EXECUTE FUNCTION fn_ty_es_config_guard();
CREATE FUNCTION fn_ty_es_intent_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE c public.ty_hr_contract%ROWTYPE;f public.ty_hr_file_asset%ROWTYPE;p public.ty_es_profile%ROWTYPE;ps public.ty_es_party%ROWTYPE;co public.ty_es_party%ROWTYPE;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签事实及来源不可删除';END IF;
 IF TG_OP='UPDATE'THEN
  IF NEW.status IS DISTINCT FROM OLD.status AND NOT(OLD.status='draft'AND NEW.status='approved'OR OLD.status='approved'AND NEW.status IN('external_draft','unknown','blocked')OR OLD.status='external_draft'AND NEW.status IN('signing','unknown','blocked')OR OLD.status='signing'AND NEW.status IN('completed','unknown','blocked')OR OLD.status='unknown'AND NEW.status IN('external_draft','signing','blocked')OR OLD.status='completed'AND NEW.status IN('accepted','blocked','unknown'))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签事实必须依核准、草稿、签署、取证和HR核定阶段推进';END IF;
  IF OLD.approved_by IS NOT NULL AND ROW(NEW.approved_by,NEW.approved_at)IS DISTINCT FROM ROW(OLD.approved_by,OLD.approved_at)OR OLD.started_by IS NOT NULL AND NEW.started_by IS DISTINCT FROM OLD.started_by THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签独立核准与明确开启人不可换绑';END IF;
  IF to_jsonb(NEW)-ARRAY['status','remote_file_id','remote_flow_id','remote_status','remote_checked_at','signed_file_id','signed_sha256','signed_on','receipt_cipher','verification_summary','revision','approved_by','approved_at','started_by','accepted_by','accepted_at','accept_ref']IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','remote_file_id','remote_flow_id','remote_status','remote_checked_at','signed_file_id','signed_sha256','signed_on','receipt_cipher','verification_summary','revision','approved_by','approved_at','started_by','accepted_by','accepted_at','accept_ref']OR NEW.revision<>OLD.revision+1 OR OLD.remote_file_id IS NOT NULL AND NEW.remote_file_id IS DISTINCT FROM OLD.remote_file_id OR OLD.remote_flow_id IS NOT NULL AND NEW.remote_flow_id IS DISTINCT FROM OLD.remote_flow_id OR OLD.signed_file_id IS NOT NULL AND ROW(NEW.signed_file_id,NEW.signed_sha256,NEW.signed_on,NEW.receipt_cipher,NEW.verification_summary)IS DISTINCT FROM ROW(OLD.signed_file_id,OLD.signed_sha256,OLD.signed_on,OLD.receipt_cipher,OLD.verification_summary)OR OLD.status='accepted' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签冻结来源与已核证据不可改写';END IF;
 END IF;
 SELECT*INTO c FROM public.ty_hr_contract WHERE id=NEW.contract_id;SELECT*INTO f FROM public.ty_hr_file_asset WHERE id=NEW.source_file_id;SELECT*INTO p FROM public.ty_es_profile WHERE id=NEW.profile_id;SELECT*INTO ps FROM public.ty_es_party WHERE id=NEW.person_party_id;SELECT*INTO co FROM public.ty_es_party WHERE id=NEW.company_party_id;
 IF ROW(NEW.group_id,NEW.company_id,NEW.person_id)IS DISTINCT FROM ROW(c.group_id,c.company_id,c.person_id)OR f.owner_kind<>'contract'OR f.owner_id<>c.id OR f.sha256<>NEW.source_sha256 OR ps.kind<>'person'OR ps.person_id<>c.person_id OR co.kind<>'company'OR co.company_id<>c.legal_entity_company_id OR ps.profile_id<>p.id OR co.profile_id<>p.id OR p.group_id<>c.group_id THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签合同、人员、真实雇主、原件与连接必须同一事实';END IF;
 IF NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,NEW.group_id,NEW.person_id)OR NEW.status='accepted'AND(NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.accepted_by,NEW.group_id,NEW.person_id)OR NOT public.fn_ty_pay_distinct_reviewer(c.created_by,NEW.accepted_by,NEW.group_id,NEW.person_id))THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签外发与签后原件须独立核定';END IF;
 IF NEW.signed_file_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ty_hr_file_asset z WHERE z.id=NEW.signed_file_id AND z.owner_kind='contract'AND z.owner_id=c.id AND z.sha256=NEW.signed_sha256)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='签后原件须归属该合同且哈希一致';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_es_intent_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_es_intent FOR EACH ROW EXECUTE FUNCTION fn_ty_es_intent_guard();
CREATE FUNCTION fn_ty_es_job_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE p public.ty_es_intent%ROWTYPE;
BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签办理历史不可删除';END IF;
 SELECT*INTO p FROM public.ty_es_intent WHERE id=NEW.intent_id;
 IF TG_OP='INSERT'THEN
  IF NEW.state<>'queued'OR p.status IN('draft','accepted','blocked')OR NEW.expected_revision<>p.revision OR NEW.step='create'AND(p.remote_file_id IS NULL OR p.remote_flow_id IS NOT NULL)OR NEW.step='upload'AND(p.remote_file_id IS NOT NULL OR p.remote_flow_id IS NOT NULL)OR NEW.step IN('start','poll','retrieve')AND p.remote_flow_id IS NULL OR NEW.step='reconcile'AND(p.status<>'unknown'OR p.remote_flow_id IS NOT NULL OR NEW.remote_claim_id IS NULL)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签任务须依当前冻结事实和明确阶段建立';END IF;
 ELSE
  IF to_jsonb(NEW)-ARRAY['state','lease_key','lease_until','error_code','finished_at','revision']IS DISTINCT FROM to_jsonb(OLD)-ARRAY['state','lease_key','lease_until','error_code','finished_at','revision']OR NEW.revision<>OLD.revision+1 OR OLD.state NOT IN('queued','running')OR OLD.state='queued'AND NEW.state<>'running'OR OLD.state='running'AND NEW.state NOT IN('succeeded','failed','unknown')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签任务冻结内容不可改写或重放';END IF;
 END IF;RETURN NEW;
END;$$;
CREATE TRIGGER ty_es_job_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_es_job FOR EACH ROW EXECUTE FUNCTION fn_ty_es_job_guard();
-- A generic native signing form must not relabel an old electronic original as
-- evidence for edited content, nor treat a pre-sign PDF as a signed paper scan.
CREATE FUNCTION fn_ty_es_native_evidence_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$
DECLARE e public.ty_es_intent%ROWTYPE;f public.ty_hr_file_asset%ROWTYPE;
BEGIN
 IF NEW.status<>'signed'OR TG_OP='UPDATE'AND OLD.status='signed'THEN RETURN NEW;END IF;
 IF EXISTS(SELECT 1 FROM public.ty_es_intent x WHERE x.source_file_id=NEW.evidence_file_id)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签待签原件不能作为手工签后原件登记，请选择本次已核签后材料';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.ty_es_intent x WHERE x.signed_file_id=NEW.evidence_file_id)THEN RETURN NEW;END IF;
 SELECT*INTO e FROM public.ty_es_intent x WHERE x.signed_file_id=NEW.evidence_file_id AND x.contract_id=NEW.id AND x.status='accepted';
 SELECT*INTO f FROM public.ty_hr_file_asset WHERE id=NEW.evidence_file_id;
 IF TG_OP<>'UPDATE'OR e.id IS NULL OR e.contract_revision<>OLD.revision OR e.contract_hash IS DISTINCT FROM OLD.source_hash OR e.contract_hash IS DISTINCT FROM NEW.source_hash OR ROW(e.group_id,e.company_id,e.person_id)IS DISTINCT FROM ROW(NEW.group_id,NEW.company_id,NEW.person_id)OR e.signed_on IS DISTINCT FROM NEW.signed_on OR f.owner_kind<>'contract'OR f.owner_id<>NEW.id OR f.sha256 IS DISTINCT FROM e.signed_sha256 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='电子签后材料须已由HR核定并对应当前合同正文、版本及主体；修改后的合同须重新收集对应签署材料';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_es_native_evidence_guard BEFORE INSERT OR UPDATE ON ty_hr_contract FOR EACH ROW EXECUTE FUNCTION fn_ty_es_native_evidence_guard();
